import {statementFixture} from './block1-statements.mjs';
export const account = '40702810111110000001';
export function cashStatement() {
  const base=statementFixture({account,inn:'9900000002',company:'ООО Тестовый пример',openingBalance:'100.00',endingBalance:'1013.92'});
  const own=[account,'9900000002','ООО Тестовый пример'];
  const buyer=['40702810999990000001','9900000003','ООО Тестовый покупатель'];
  const row=(n,amount,payer,recipient,purpose)=>['СекцияДокумент=Платежное поручение','Номер='+n,'Дата=15.07.2026','Сумма='+amount,
    'ПлательщикСчет='+payer[0],'ПлательщикИНН='+payer[1],'Плательщик='+payer[2],
    'ПолучательСчет='+recipient[0],'ПолучательИНН='+recipient[1],'Получатель='+recipient[2],
    'НазначениеПлатежа='+purpose,'КонецДокумента'].join('\n');
  return [base.split('СекцияДокумент=')[0].replace(/ВсегоПоступило=.+/,'ВсегоПоступило=1020.15').replace(/ВсегоСписано=.+/,'ВсегоСписано=106.23'),
    row(101,'1000.12',buyer,own,'Оплата по договору за выполненные работы'),
    row(102,'20.03',buyer,own,'Возврат ранее перечисленных средств за товар'),
    row(103,'91.17',own,buyer,'Погашение основного долга по кредитному договору'),
    row(104,'15.06',own,[buyer[0],'9900000008','УФК'],'Единый налоговый платеж в бюджет'),'КонецФайла'].join('\n');
}

export function ownLegsStatement() {
  const second='40702810111110000002';
  const base=statementFixture({account,inn:'9900000002',company:'ООО Тестовый пример'});
  const header=base.split('СекцияРасчСчет')[0];
  const section=(n,opening,credit,debit,closing)=>[
    'СекцияРасчСчет','ДатаНачала=01.07.2026','ДатаКонца=31.07.2026','РасчСчет='+n,
    'НачальныйОстаток='+opening,'ВсегоПоступило='+credit,'ВсегоСписано='+debit,'КонечныйОстаток='+closing,'КонецРасчСчет',
  ].join('\n');
  const doc=(posting)=>['СекцияДокумент=Платежное поручение','Номер=7','Дата=12.07.2026',posting+'=12.07.2026','Сумма=48.37',
    'ПлательщикИНН=9900000002','ПлательщикСчет='+account,'Плательщик=ООО Тестовый пример',
    'ПолучательИНН=9900000002','ПолучательСчет='+second,'Получатель=ООО Тестовый пример',
    'НазначениеПлатежа=Перевод между своими счетами','КонецДокумента'].join('\n');
  return [header,section(account,50,0,48.37,1.63),section(second,0,48.37,0,48.37),'',doc('ДатаСписано'),'',doc('ДатаПоступило'),'КонецФайла'].join('\n');
}
